css:
[data-bz-section="pg-form-head"] .bz-block { padding-block: 0; }
[data-bz-section="pg-form-head"] .bz-block p { margin: 0; }
[data-bz-section="pg-form-head"] .bz-col[data-bz-node="pfh-crumbs"] { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-bottom: 16px; font-size: 13px; line-height: normal; color: var(--copy-on-dark); }
[data-bz-section="pg-form-head"] .bz-col[data-bz-node="pfh-crumbs"] p { font-size: 13px; line-height: normal; color: var(--copy-on-dark); }
[data-bz-section="pg-form-head"] .bz-col[data-bz-node="pfh-crumbs"] a { color: inherit; text-decoration: none; }
[data-bz-section="pg-form-head"] .bz-col[data-bz-node="pfh-crumbs"] a:hover { color: var(--card); }
[data-bz-section="pg-form-head"] .bz-block[data-bz-node^="pfh-"] { display: flex; align-items: baseline; }
[data-bz-section="pg-form-head"] .bz-block[data-bz-node^="pfh-trail"]::after { content: "/"; margin-left: 8px; }
[data-bz-section="pg-form-head"] .bz-block[data-bz-node="pfh-home"]::after { content: "/"; margin-left: 8px; }
[data-bz-section="pg-form-head"] .bz-block[data-bz-node="pfh-current"] p { color: var(--card); }
[data-bz-section="pg-form-head"] [data-bz-node="pfh-h"] h1 { font-size: 36px; line-height: normal; margin: 0 0 12px; color: var(--card); }
[data-bz-section="pg-form-head"] [data-bz-node="pfh-note"] p { font-size: 15px; line-height: 1.5; color: #c9cbd0; max-width: 780px; }
@media (max-width: 640px) { [data-bz-section="pg-form-head"] [data-bz-node="pfh-h"] h1 { font-size: 30px; } }
